/**
 * Data table Node - Version 1.1
 * Discriminator: resource=table, operation=clear
 */


/** Clear all rows from a data table */
export type DataTableV11TableClearParams = {
  resource: 'table';
  operation: 'clear';
/**
 * Data table
 * @builderHint Default to mode: 'list' which is easier for users to set up
 * @searchListMethod tableSearch
 * @default {"mode":"list","value":""}
 */
    dataTableId?: { __rl: true; mode: 'list' | 'name' | 'id'; value: string; cachedResultName?: string };
};

export type DataTableV11TableClearOutput = {
  deletedCount?: number;
  success?: boolean;
};

export type DataTableV11TableClearNode = {
  type: 'n8n-nodes-base.dataTable';
  version: 1.1;
  config: NodeConfig<DataTableV11TableClearParams>;
  output?: Items<DataTableV11TableClearOutput>;
};